def parse_query(tokens):
    parts = {'columns': [], 'roots': [], 'where': [], 'groupby': [], 'orderby': [], 'limit': None, 'offset': None, 'into': 'tabs'}
    current = 'columns'
    i = 0
    while i < len(tokens):
        t = tokens[i]
        tu = t.upper()
        if tu == 'FROM': current = 'roots'; i += 1
        elif tu == 'WHERE': current = 'where'; i += 1
        elif tu == 'GROUP' and i+1 < len(tokens) and tokens[i+1].upper() == 'BY': current = 'groupby'; i += 2
        elif tu == 'ORDER' and i+1 < len(tokens) and tokens[i+1].upper() == 'BY': current = 'orderby'; i += 2
        elif tu == 'LIMIT': i += 1; parts['limit'] = tokens[i]; i += 1; current = None
        elif tu == 'OFFSET': i += 1; parts['offset'] = tokens[i]; i += 1; current = None
        elif tu == 'INTO': i += 1; parts['into'] = tokens[i].lower(); i += 1; current = None
        else:
            if current == 'columns':
                if t != ',': parts['columns'].append(t)
                i += 1
            elif current == 'roots':
                parts['roots'].append(t)
                i += 1
            elif current == 'where':
                parts['where'].append(t)
                i += 1
            elif current == 'groupby':
                if t != ',': parts['groupby'].append(t)
                i += 1
            elif current == 'orderby':
                if t != ',': parts['orderby'].append(t)
                i += 1
            else: i += 1
    return parts

def get_roots(root_tokens):
    if not root_tokens: return [('.', {})]
    roots = []
    curr_root = None
    curr_opts = {}
    i = 0
    while i < len(root_tokens):
        t = root_tokens[i]
        if t == ',':
            if curr_root: roots.append((curr_root, curr_opts))
            curr_root = None; curr_opts = {}; i += 1
            continue
        if curr_root is None:
            curr_root = t; i += 1
        else:
            tu = t.upper()
            if tu in ('DEPTH', 'MAXDEPTH'):
                i += 1; curr_opts['maxdepth'] = int(root_tokens[i]); i += 1
            elif tu == 'MINDEPTH':
                i += 1; curr_opts['mindepth'] = int(root_tokens[i]); i += 1
            elif tu == 'SYMLINKS':
                curr_opts['symlinks'] = True; i += 1
            elif tu in ('GITIGNORE', 'GIT'):
                curr_opts['gitignore'] = True; i += 1
            else:
                roots.append((curr_root, curr_opts))
                curr_root = t; curr_opts = {}; i += 1
    if curr_root: roots.append((curr_root, curr_opts))
    return roots

