def translate_where(where_tokens):
    res = []
    i = 0
    while i < len(where_tokens):
        t = where_tokens[i]
        tl = t.lower()
        if re.match(r'^\d+(\.\d+)?[a-zA-Z]+$', t):
            val = parse_size(t)
            res.append(str(val) if val is not None else t)
        elif tl == 'today':
            res.append("'" + datetime.now().strftime('%Y-%m-%d') + "'")
        elif t == '=':
            # Check if next token is a glob
            if i + 1 < len(where_tokens) and ('*' in where_tokens[i+1] or '?' in where_tokens[i+1]):
                res.append('GLOB')
            else:
                res.append('=')
        elif t == '~=':
            res.append('REGEXP')
        else:
            res.append(t)
        i += 1
    return " ".join(res)

def capitalize_col(name):
    if name.lower() == 'count(*)': return 'count(*)'
    parts = re.split(r'(\W+)', name)
    return "".join([p.capitalize() if p.isalnum() else p for p in parts])

def run_query(query):
    tokens = tokenize(query)
    parts = parse_query(tokens)
    roots = get_roots(parts['roots'])
    files_data = []
    for root, opts in roots:
        if os.path.isdir(root):
            try:
                with os.scandir(root) as it:
                    for entry in it:
                        walk(entry.path, entry.name, opts, 1, files_data)
            except OSError: pass

    if not files_data: return

    conn = sqlite3.connect(":memory:")
    conn.create_function("REGEXP", 2, lambda expr, item: 1 if re.search(expr, str(item)) else 0)

    keys = list(files_data[0].keys())
    col_types = {'size': 'INTEGER', 'uid': 'INTEGER', 'gid': 'INTEGER', 'is_dir': 'INTEGER', 'is_file': 'INTEGER', 'is_symlink': 'INTEGER'}
    cols = ", ".join([f"{k} {col_types.get(k, 'TEXT')}" for k in keys])
    conn.execute(f"CREATE TABLE files ({cols})")

    for f in files_data:
        conn.execute(f"INSERT INTO files VALUES ({','.join(['?']*len(keys))})", [f[k] for k in keys])

    # Construct the final SQL
    sql_cols = ", ".join(parts['columns']) if parts['columns'] else "*"
    sql = f"SELECT {sql_cols} FROM files"
    if parts['where']:
        sql += " WHERE " + translate_where(parts['where'])
    if parts['groupby']:
        sql += " GROUP BY " + ", ".join(parts['groupby'])
    if parts['orderby']:
        sql += " ORDER BY " + ", ".join(parts['orderby'])
    if parts['limit']:
        sql += " LIMIT " + parts['limit']
    if parts['offset']:
        sql += " OFFSET " + parts['offset']

    try:
        cursor = conn.execute(sql)
        rows = cursor.fetchall()
        col_names = [d[0] for d in cursor.description]

        output_format = parts['into']
        if output_format == 'json':
            res = []
            for row in rows:
                obj = {}
                for i, val in enumerate(row):
                    obj[capitalize_col(col_names[i])] = str(val) if val is not None else ""
                res.append(obj)
            print(json.dumps(res, separators=(',', ':')))
        elif output_format == 'csv':
            writer = csv.writer(sys.stdout)
            for row in rows: writer.writerow(row)
        elif output_format == 'html':
            print(f"<html><head><title>{query}</title></head><body><table><tr><th colspan=\"{len(col_names)}\">{query}</th></tr>")
            for row in rows:
                print("<tr>" + "".join([f"<td>{r}</td>" for r in row]) + "</tr>")
            print("</table></body></html>")
        elif output_format == 'list':
            for row in rows:
                sys.stdout.write(str(row[0]) + '\0')
        else: # tabs
            for row in rows:
                print("\t".join([str(r) if r is not None else "" for r in row]))

    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)

def main():
    if len(sys.argv) < 2: return
    if sys.argv[1] in ('-i', '--interactive'):
        while True:
            try:
                line = input("> ")
                if line.lower() in ('exit', 'quit'): break
                run_query(line)
            except EOFError: break
    else:
        run_query(" ".join(sys.argv[1:]))

if __name__ == "__main__":
    main()
