import sys, os, sqlite3, re, fnmatch, json, csv
from datetime import datetime

EXTENSIONS = {
    'is_archive': ['.7z', '.bz2', '.bzip2', '.gz', '.gzip', '.lz', '.rar', '.tar', '.xz', '.zip'],
    'is_audio': ['.aac', '.aiff', '.amr', '.flac', '.gsm', '.m4a', '.m4b', '.m4p', '.mp3', '.ogg', '.wav', '.wma'],
    'is_book': ['.azw3', '.chm', '.djv', '.djvu', '.epub', '.fb2', '.mobi', '.pdf'],
    'is_doc': ['.accdb', '.doc', '.docm', '.docx', '.dot', '.dotm', '.dotx', '.mdb', '.odp', '.ods', '.odt', '.pdf', '.potm', '.potx', '.ppt', '.pptm', '.pptx', '.rtf', '.xlm', '.xls', '.xlsm', '.xlsx', '.xlt', '.xltm', '.xltx', '.xps'],
    'is_image': ['.bmp', '.exr', '.gif', '.heic', '.jpeg', '.jpg', '.jxl', '.png', '.psb', '.psd', '.svg', '.tga', '.tiff', '.webp'],
    'is_video': ['.3gp', '.avi', '.flv', '.m4p', '.m4v', '.mkv', '.mov', '.mp4', '.mpeg', '.mpg', '.webm', '.wmv'],
}

KNOWN_COLS = {'name', 'path', 'abspath', 'size', 'hsize', 'fsize', 'uid', 'gid', 'user', 'group', 'modified', 'created', 'accessed', 'is_dir', 'is_file', 'is_symlink', 'extension'}

def format_hsize(size):
    if size < 1024: return f"{size}B"
    for unit in ['KiB', 'MiB', 'GiB', 'TiB']:
        size /= 1024.0
        if size < 1024.0: return f"{size:.2f}{unit}"
    return f"{size:.2f}PiB"

def parse_size(s):
    m = re.match(r'^(\d+(?:\.\d+)?)([a-zA-Z]*)$', s)
    if not m: return None
    val = float(m.group(1))
    u = m.group(2).lower()
    units = {'b':1, 'k':1024, 'kb':1000, 'kib':1024, 'm':1024**2, 'mb':1000**2, 'mib':1024**2, 'g':1024**3, 'gb':1000**3, 'gib':1024**3, 't':1024**4, 'tb':1000**4, 'tib':1024**4}
    return int(val * units.get(u, 1))

def tokenize(query):
    pattern = r"'(?:''|[^'])*'|\"(?:\"\"|[^\"])*\"|`(?:``|[^`])*`|\d+\.\d+[a-zA-Z]*|\d+[a-zA-Z]*|\w+|>=|<=|!=|<>|===|!==|~=|!=~|[=><,()/*{}]|\S"
    return [m.group(0) for m in re.finditer(pattern, query)]

def parse_query(tokens):
    parts = {'columns': [], 'roots': [], 'where': [], 'groupby': [], 'orderby': [], 'limit': None, 'offset': None, 'into': 'tabs'}
    current = 'columns'
    i = 0
    while i < len(tokens):
        t = tokens[i]; tu = t.upper()
        if tu == 'FROM': current = 'roots'; i += 1
        elif tu == 'WHERE': current = 'where'; i += 1
        elif tu == 'GROUP' and i+1 < len(tokens) and tokens[i+1].upper() == 'BY': current = 'groupby'; i += 2
        elif tu == 'ORDER' and i+1 < len(tokens) and tokens[i+1].upper() == 'BY': current = 'orderby'; i += 2
        elif tu == 'LIMIT': i += 1; parts['limit'] = tokens[i]; i += 1; current = None
        elif tu == 'OFFSET': i += 1; parts['offset'] = tokens[i]; i += 1; current = None
        elif tu == 'INTO': i += 1; parts['into'] = tokens[i].lower(); i += 1; current = None
