            for r in rows: sys.stdout.write(str(r[0]) + '\0')
        else:
            for r in rows: print("\t".join([str(v) if v is not None else "" for v in r]))
    except Exception as e: pass

def main():
    if len(sys.argv) < 2: return
    if sys.argv[1] in ('-i', '--interactive'):
        while True:
            try: line = input(); run_query(line)
            except EOFError: print("CTRL-D"); break
            except: pass
    else: run_query(" ".join(sys.argv[1:]))

if __name__ == "__main__": main()
